async function api(path,{signal}={}){if(state.housing==='new'){if(path.startsWith('/api/city?'))path=path.replace('/api/city?','/api/new-homes?scope=city&');else if(path.startsWith('/api/districts?'))path=path.replace('/api/districts?','/api/new-homes?scope=district&');}const response=await fetch(path,{cache:'no-store',signal});const data=await response.json();if(!response.ok||data.ok===false)throw new Error(data.error??'来源暂不可用');return data;}
