function cityFootprint(){const region=state.districts?.region;if(!region)return[];return region.features.flatMap(f=>(f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates).map(raw=>{const rings=raw.map(r=>r.map(p=>mercator(p[0],p[1]))),xs=rings[0].map(p=>p.x),ys=rings[0].map(p=>p.y);return{rings,box:[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)]};}));}
