async function fetchNewNational(month,force,onBatch){const target=month??'latest';let offset=0,all=[],errors=[],first=null;do{const data=await api('/api/new-homes?scope=national&month='+(first?.month??target)+'&offset='+offset+'&refresh='+(force?'1':'0'));first??=data;all.push(...data.records);errors.push(...data.errors);onBatch?.(all,data);offset=data.nextOffset;}while(offset!==null);return{...first,records:all,errors,coverage:{regions:all.length,mappedCities:all.filter(r=>Number.isFinite(r.price)).length,unmapped:[]},latestSourceMonth:first.month,status:'live',storage:{saved:true,method:'new_home_data_cache'}};}
