async function switchHousing(housing){if(housing===state.housing)return;stopPlay();monthToken++;cityToken++;communityToken++;viewports.cancel();const selected=state.city;state.housing=housing;frameCache=framesByHousing[housing];extraHistories.clear();comparisonMonth=null;state.trend=false;state.top=false;map.jumpTo({pitch:55});viewportAutoMonth=true;currentViewport=null;state.month=null;state.months=[];state.records=[];state.market=null;state.cityData=state.districts=state.community=null;state.communities=[];state.highlights=[];map.setMaxZoom(housing==='new'?12:18);$('#resaleHomes').setAttribute('aria-pressed',String(housing==='resale'));$('#newHomes').setAttribute('aria-pressed',String(housing==='new'));updateTimelineLabels();updateUI();draw();analysisNote('正在读取'+(housing==='new'?'新房':'二手房')+'独立数据层…');const loading=refresh();if(selected)selectCity(selected);await loading;}
