async function loadHighlights(token){if(state.city?.name!=='北京'||state.housing==='new')return;try{const data=await api('/api/viewport?city=北京&bbox=115.4,39.4,117.6,41.1&month=latest&collect=1&focus=expensive');if(token!==cityToken)return;state.highlights=data.records;const rows=new Map(state.communities.map(r=>[r.id+':'+r.month+':'+r.priceType,r]));for(const r of data.records)rows.set(r.id+':'+r.month+':'+r.priceType,r);state.communities=[...rows.values()];renderExpensive();}catch{if(token===cityToken)$('#expensiveNote').textContent='高价样本读取失败，放大至城区后可继续获取。';}}
