function withComparison(rows){if(!state.month||!rows.length)return rows;const base= comparisonMonth??shift(state.month,-12),cached=frameCache.get(base)?.records??[];return rows.map(r=>{const prior=r.history?.find(p=>p.month===base)??cached.find(p=>(p.id===r.id||p.name===r.name)&&(!r.city||p.city===r.city));const price=prior?.price??(base===shift(r.month,-12)?r.lastYear:null);return{...r,comparisonMonth:base,changeSinceStart:Number.isFinite(price)&&price>0?(r.price/price-1)*100:null};});}
