map.on('dataloading',e=>{if(e.dataType==='style'||e.source?.type==='vector'||e.source?.type==='raster'){watchMap();}});
map.on('idle',()=>{terrainLayer?.maskWater();clearTimeout(mapWaitTimer);mapWaitStarted=0;if(mapFailed){mapMessage('部分地图资源未加载，可重试。',true);}else{$('#loading').classList.add('hidden');$('#loading').dataset.state='ready';}});
