function mergeHistory(data){const records=new Map(data.records.map(r=>[r.name,r]));for(const r of extraHistories.values()){const p=r.history.find(p=>p.month===data.month);if(!p)continue;const prior=r.history.find(p=>p.month===shift(data.month,-1)),year=r.history.find(p=>p.month===shift(data.month,-12));records.set(r.name,{...r,month:data.month,price:p.price,mom:prior?(p.price/prior.price-1)*100:null,yoy:year?(p.price/year.price-1)*100:null});}return{...data,records:[...records.values()]};}
async function preparePlayback(){stopPlay();const generation=playGeneration;state.preparing=true;$('#play').setAttribute('aria-label','取消准备播放');$('#playIcon').innerHTML='<path d="M5 4h4v12H5zm7 0h4v12h-4z"/>';const local=!!state.city,district=districtView();let months;
 if(district){if(!state.districts?.entities){state.districts=await api('/api/districts?city=北京&month='+state.month);if(generation!==playGeneration)return;draw();}const available=state.districts.availableMonths??[];const index=available.indexOf(state.month);months=index>=available.length-1||index<0?available.slice(-12):available.slice(index,index+12);if(months.length<2){stopPlay();toast('所选区县暂无可播放的连续历史');return;}}
 else if(local){months=[...new Set([...state.communities,...state.imported].flatMap(r=>[r.month,...(r.history??[]).map(p=>p.month)]))].sort();if(months.length<2){stopPlay();toast('小区目前只有一个真实月份，尚不能播放历史变化');return;}}
 else{const completed=state.housing==='new'?state.market.month:state.market?.latestCompletedMonth??shift(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()).replace('/','-'),-1),available=state.months.filter(m=>m<=completed),index=available.indexOf(state.month);months=index>=available.length-1||index<0?available.slice(-12):available.slice(index,index+12);}
 const prepared=new Map();let cursor=0,finished=0;const tasks=Array.from({length:Math.min(3,months.length)},async()=>{for(;;){const i=cursor++;if(i>=months.length||generation!==playGeneration)return;const month=months[i];try{let data=frameCache.get(month);if(!data)data=local||state.housing==='new'?{...state.market,month,records:[]}:await api('/api/market?month='+month+'&refresh=0');data=mergeHistory(data);if(generation!==playGeneration)return;frameCache.set(month,data);prepared.set(month,data);}catch{}finished++;if(generation===playGeneration)setStatus(`准备历史 ${finished}/${months.length}`);}});await Promise.all(tasks);if(generation!==playGeneration)return;
 playMonths=months.filter(m=>prepared.has(m));if(playMonths.length<2){stopPlay();toast('可用历史不足，未生成替代价格');return;}
 comparisonMonth=playMonths[0];viewportAutoMonth=false;if(terrainLayer)terrainLayer.mode=state.trend?'change':'price';setStatus('后台准备渐变地形…');for(const month of playMonths){if(generation!==playGeneration)return;const rows=local?(district?state.districts.entities:[...state.communities,...state.imported]).map(r=>{const p=r.history?.find(p=>p.month===month);return p?{...r,...p}:r.month===month?r:null;}).filter(Boolean):prepared.get(month).records.filter(r=>r.lon!==null&&r.price!==null);await terrainLayer?.prepare(withComparison(rows),local);}
 if(generation!==playGeneration)return;state.preparing=false;state.playing=true;$('#play').setAttribute('aria-label','暂停时间变化');playIndex=0;applyFrame(frameCache.get(playMonths[0]));playTimer=setTimeout(playStep,700);if(playMonths.length<months.length)toast('缺少来源数据的月份已跳过');}
function playStep(){if(!state.playing)return;playIndex++;if(playIndex>=playMonths.length){stopPlay(true);return;}applyFrame(frameCache.get(playMonths[playIndex]));playTimer=setTimeout(playStep,700);}
$('#play').onclick=()=>{if(state.playing||state.preparing)stopPlay();else preparePlayback().catch(()=>{stopPlay();toast('历史准备失败，可稍后重试');});};
$('#time').oninput=e=>setMonth(state.months[Number(e.target.value)]);$('#latest').onclick=()=>{viewportAutoMonth=true;if(districtView())viewports.queue(false,0);else if(state.city)viewports.queue(true,0);else setMonth(state.months.at(-1));};$('#refresh').onclick=async()=>{if(!state.city){await refresh(state.month,{force:true});return;}const c=state.city;$('#refresh').disabled=true;try{viewports.queue(true,0);const data=await api('/api/city?city='+encodeURIComponent(c.name)+'&refresh=1');if(state.city?.name===c.name){state.cityData=data;updateUI();}}catch(error){toast('部分来源刷新失败：'+error.message);}finally{$('#refresh').disabled=false;}};$('#search').oninput=search;$('#search').onkeydown=e=>{if(e.key==='Escape')$('#searchResults').classList.add('hidden');};
$('#national').onclick=()=>{stopPlay();cityToken++;communityToken++;viewports.cancel();currentViewport=null;state.city=state.cityData=state.districts=state.community=null;state.communities=[];state.highlights=[];const cached=frameCache.get(nationalMonth);if(cached){state.market=cached;state.records=cached.records;state.month=cached.month;}else if(state.market?.month)state.month=state.market.month;updateUI();draw();map.flyTo({center:[108,33],zoom:innerWidth<760?2.55:3.6,pitch:state.trend?0:45,bearing:state.trend?0:-10,padding:padding(),duration:reduced?0:1200});};$('#cityScope').onclick=()=>{if(state.city)selectCity(state.city);else{$('#search').focus();toast('搜索城市或点击地图中的价格柱');}};
$('#backToCity').onclick=()=>{state.community=null;communityToken++;updateUI();draw();};$('#loadCommunities').onclick=()=>loadCommunities();$('#moreCommunities').onclick=()=>loadCommunities(true);$('#togglePanel').onclick=()=>{$('.sidebar').classList.toggle('expanded');$('#togglePanel').textContent=$('.sidebar').classList.contains('expanded')?'⌃':'⌄';};
$('#range12').onclick=()=>{state.range=12;$('#range12').classList.add('active');$('#range36').classList.remove('active');chart();};$('#range36').onclick=()=>{state.range=36;$('#range36').classList.add('active');$('#range12').classList.remove('active');chart();};
function updateMetricUI(){const view=metricView(state.trend);document.body.dataset.metric=view.id;$('#priceMode').setAttribute('aria-pressed',String(!state.trend));$('#trendMode').setAttribute('aria-pressed',String(state.trend));$('#priceMode').disabled=$('#trendMode').disabled=!state.month;const base=state.month?(comparisonMonth??shift(state.month,-12)):'—';$('#metricTitle').textContent=state.trend?`累计涨跌 · ${base} → ${state.month}`:'价格高度 · 元/㎡';$('#metricDescription').textContent=view.description;$('.anchor-explanation').textContent=state.trend?'比较同一区域的两个真实月份；灰色不是持平。':'圆环标记地面位置，连线对应价格高度。';$('#priceUnit').textContent=state.trend?'':'元 / m²';$('#priceValue').className='';$('#cityListSection .section-line>span').textContent=state.trend?'城市累计涨跌':'已获取城市';$('#communitySection .section-line>span').textContent=state.trend?'小区累计涨跌':'公开小区价格';if(state.city&&!districtView())$('#communityList').replaceChildren(...[...state.communities,...state.imported].filter(r=>r.city===state.city.name).map(pointRecord).filter(r=>r&&(!currentViewport||inBounds(r,currentViewport.bbox))).map(r=>entityRow(r,true)));if(!state.trend)return;const record=selectedRecord(),selected=record?withComparison([{...record,history:state.community?.history??state.cityData?.history??record.history}])[0]:null,rows=terrainRecords().records,values=rows.map(r=>r.changeSinceStart).filter(Number.isFinite).sort((a,b)=>a-b);$('#placeSub').textContent=state.community?'小区累计涨跌 / 相同价格口径':districtView()?'二手房区县累计涨跌 / 放大查看小区':'城市累计涨跌 / 相同价格口径';if(state.housing==='new')$('#placeSub').textContent=districtView()?'新房区县累计涨跌 / 非逐楼盘价格':'新房城市累计涨跌';$('#districtSection>p').textContent='蓝色下降，橙色上涨；相对同一比较基期。';$('#readingLabel').textContent=state.city?'所选'+(state.community?'小区':'城市')+'累计涨跌':'可比较城市累计涨跌中位数';$('#priceValue').textContent=state.city?(selected?deltaText(selected.changeSinceStart):'缺少基期'):values.length?deltaText(values[Math.floor(values.length/2)]):'缺少基期';$('#priceValue').className=hue(state.city?selected?.changeSinceStart:values[Math.floor(values.length/2)]);$('#readingMeta').textContent=`${base} → ${state.month??'—'}${state.city?' / 仅比较相同区域、相同口径':' / '+values.length+'个可比较城市'}`;$('#districtSection .section-line>span').textContent='北京16区累计涨跌';$('#cityListSection .section-line>span').textContent='城市累计涨跌';$('#communitySection .section-line>span').textContent='小区累计涨跌';$('#communityList').replaceChildren(...[...state.communities,...state.imported].filter(r=>r.city===state.city?.name).map(pointRecord).filter(r=>r&&(!currentViewport||inBounds(r,currentViewport.bbox))).map(r=>entityRow(r,true)));analysisNote(trendSummary(rows));}
function setMetricMode(trend){if(trend===state.trend||!state.month)return;stopPlay();if(trend){priceCamera={pitch:map.getPitch(),bearing:map.getBearing(),top:state.top};if(!comparisonMonth)comparisonMonth=state.housing==='new'?state.months[0]:shift(state.month,-12);}state.trend=trend;state.prices=true;map.easeTo({pitch:trend?0:priceCamera.pitch,bearing:trend?0:priceCamera.bearing,duration:reduced?0:500});if(!trend){state.top=priceCamera.top;$('#priceValue').className='';$('#cityListSection .section-line>span').textContent='已获取城市';$('#communitySection .section-line>span').textContent='公开小区价格';}updateUI();draw();analysisNote(trend?trendSummary(terrainRecords().records):'高度与金色深浅表示单价；圆环为真实地面位置。');}
