function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
$('#exportData').onclick=()=>{const data={marketType:state.housing,month:state.month,fetchedAt:state.market?.fetchedAt,priceType:'mixed_explicit_per_record',cities:currentRecords(),communities:state.housing==='resale'?[...state.communities,...state.imported]:[],districts:districtRecords()};saveBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`房价来源记录-${state.month}.json`);};
$('#screenshot').onclick=()=>{map.once('render',()=>{try{const source=map.getCanvas(),c=document.createElement('canvas');c.width=source.width;c.height=source.height;const ctx=c.getContext('2d'),scale=c.width/innerWidth;ctx.drawImage(source,0,0);ctx.scale(scale,scale);ctx.fillStyle='#ffffffed';ctx.fillRect(18,18,330,73);ctx.fillRect(18,innerHeight-65,Math.min(innerWidth-36,620),48);ctx.fillStyle='#263c50';ctx.font='500 23px sans-serif';ctx.fillText('房价地形',30,48);ctx.font='11px sans-serif';ctx.fillText(`${state.month} / ${state.community?.name??state.city?.name??'全国城市'} / 空间插值地形`,30,72);ctx.fillText(`价格来源：房天下公开页面；获取于 ${stamp(state.market?.fetchedAt)}。`,30,innerHeight-44);ctx.fillText('曲面为空间插值，非逐点实价 · © OpenStreetMap contributors / OpenFreeMap / OpenMapTiles',30,innerHeight-26);c.toBlob(blob=>{if(blob)saveBlob(blob,`房价地形-真实数据-${state.month}.png`);});}catch{toast('截图失败，请等待地图加载完成再试');}});map.triggerRepaint();};
