$('#importData').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('文件请控制在10MB以内');const data=JSON.parse(await file.text()),rows=data.records;if(!Array.isArray(rows)||!rows.length||rows.length>30000)throw new Error('需要包含records数组，最多30000条');const entities=new Map();for(const r of rows){if(typeof r.id!=='string'||typeof r.city!=='string'||typeof r.name!=='string'||!/^20\d{2}-(0[1-9]|1[0-2])$/.test(r.month)||!Number.isFinite(r.price)||r.price<=0||r.price>5000000||!Number.isFinite(r.lon)||!Number.isFinite(r.lat)||r.lon<73||r.lon>136||r.lat<18||r.lat>54||!['listing_reference','platform_reference','transaction_average'].includes(r.priceType))throw new Error('字段不完整或无效：需要id/city/name/lon/lat/month/price/priceType，坐标必须为WGS84');const key=r.city+':'+r.id,item=entities.get(key)??{...r,history:[],imported:true,sourceUrl:/^https:\/\//.test(r.sourceUrl??'')?r.sourceUrl:'https://www.openstreetmap.org/',fetchedAt:new Date().toISOString(),historyNote:'用户导入数据，未独立核验；只保存在当前浏览器。'};item.history=item.history.filter(p=>p.month!==r.month);item.history.push({month:r.month,price:r.price});entities.set(key,item);}state.imported=[...entities.values()].map(r=>{r.history.sort((a,b)=>a.month.localeCompare(b.month));return{...r,...r.history.at(-1)};});localStorage.setItem('price-terrain-import-v1',JSON.stringify(state.imported));const names=[...new Set(state.imported.map(r=>r.city))];if(state.city){$('#communityList').replaceChildren(...[...state.communities,...state.imported.filter(r=>r.city===state.city.name)].map(r=>entityRow(r,true)));}toast(`已导入${state.imported.length}个小区，覆盖${names.length}座城市；点击小区查看趋势`);draw();}catch(error){toast('导入失败：'+error.message);}e.target.value='';};
try{state.imported=JSON.parse(localStorage.getItem('price-terrain-import-v1')??'[]');}catch{}
